    [/^累積爬升 ↑([\d.]+)m$/, m => `Pendakian ↑${m[1]}m`],
    [/^全長約 ([\d.]+)km$/, m => `Panjang ~${m[1]} km`],
    [/^(暫停開放|部分封閉|封閉|注意)（(.+)）$/, m => `${tx(m[1]) || m[1]} (${tx(m[2]) || m[2]})`],
    [/^(輕鬆|一般|進階|挑戰|困難|雪季)\(估\)$/, m => `${tx(m[1]) || m[1]} (perkiraan)`],
    [/^([\d.]+) km（估）$/, m => `${m[1]} km (perkiraan)`],
    [/^資料來源：林業及自然保育署即時路況$/, () => "Sumber: Status live trail Dinas Kehutanan"],
    [/^即時更新於 (.+)$/, m => `diperbarui ${m[1]}`],
    [/^[^、]{1,10}(?:、[^、]{1,10})+$/, m => {
      const parts = m[0].split("、"); let hit = false;
      const out = parts.map(p => { const r = tx(p.trim()); if (r) hit = true; return r || p; });
      return hit ? out.join(", ") : null;
    }],
    [/^[^　]+(?:　[^　]+)+$/, m => {
      const parts = m[0].split("　"); let hit = false;
      const out = parts.map(p => { const r = tx(p.trim()); if (r) hit = true; return r || p; });
      return hit ? out.join("　") : null;
    }]
